#!/usr/bin/env node
// Copies the mtg-master skill (../mtg-master) into lib/skill/content.ts so the app's
// system prompt is built from the skill itself. Run after editing the skill:
//   npm run sync-skill            (write)
//   npm run sync-skill -- --check (fail if content.ts is out of date; used in CI)
// The generated file is committed, so deploys that only see web/ (e.g. Vercel with
// Root Directory = web) still work.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const skillDir = join(here, "..", "..", "mtg-master");
const out = join(here, "..", "lib", "skill", "content.ts");
const check = process.argv.includes("--check");

if (!existsSync(join(skillDir, "SKILL.md"))) {
  console.log(`sync-skill: ${skillDir} not found; keeping the committed lib/skill/content.ts`);
  process.exit(0);
}

const files = ["SKILL.md", "references/commander.md", "references/lookup.md", "references/constructed.md", "references/rules.md"];
const read = (f) => readFileSync(join(skillDir, f), "utf8");
const skill = read("SKILL.md");
const version = (read("../README.md").match(/\*\*(\d+\.\d+\.\d+)\*\*/) || [])[1] || "unknown";

const entries = Object.fromEntries(files.map((f) => [f, read(f)]));
const body =
  `// GENERATED by scripts/sync-skill.mjs from ../mtg-master — do not edit by hand.\n` +
  `export const SKILL_VERSION = ${JSON.stringify(version)};\n` +
  `export const SKILL_FILES: Record<string, string> = ${JSON.stringify(entries, null, 2)};\n`;

if (check) {
  const current = existsSync(out) ? readFileSync(out, "utf8") : "";
  if (current !== body) {
    console.error("lib/skill/content.ts is out of date with ../mtg-master. Run: npm run sync-skill");
    process.exit(1);
  }
  console.log("sync-skill: up to date");
} else {
  writeFileSync(out, body);
  console.log(`sync-skill: wrote lib/skill/content.ts (${files.length} files, skill ${version}, ${skill.length} chars in SKILL.md)`);
}
